def factorized_projections(config, layer_idx: int) -> dict:
    factorized_map = getattr(config, "factorized_map", None)
    if factorized_map is None or layer_idx is None or layer_idx >= len(factorized_map):
        return {"up": False, "gate": False, "down": False}

    layer_map = factorized_map[layer_idx]
    return {key: bool(layer_map.get(key, False)) for key in ("up", "gate", "down")}


def shared_projection_rank(config, layer_idx: int, group_idx: int) -> int:
    return int(config.shared_proj_ranks[layer_idx][group_idx])


class MixtralBlockSparseTop2MLP(nn.Module):
    def __init__(
        self,
        config: MixtralConfig,
        layer_idx: int,
        expert_idx: int,
        shared_weights: nn.ParameterDict | None = None,
    ):
        super().__init__()

        self.ffn_dim = config.intermediate_size
        self.hidden_dim = config.hidden_size

        compressed_int_size = self.ffn_dim
        if config.int_ranks[layer_idx] is not None:
            compressed_int_size = config.int_ranks[layer_idx][expert_idx]

        self.latent_w1, self.latent_w2, self.latent_w3 = False, False, False

        # w1 = gate_proj, w2 = down_proj, w3 = up_proj
        if shared_weights is None:
            # occurs when weight is not compressed with Factorization, likely only Nystrom
            self.w1 = nn.Linear(self.hidden_dim, compressed_int_size, bias=False)
            self.w2 = nn.Linear(compressed_int_size, self.hidden_dim, bias=False)
            self.w3 = nn.Linear(self.hidden_dim, compressed_int_size, bias=False)
        else:
            flipped_down = config.flipped_down

            # Every expert reads its rank from the shared projection group it
            # was assigned to during compression.
            group_idx = 0
            group_indices = getattr(config, "expert_to_shared_proj", None)
            if group_indices is not None:
                group_idx = group_indices[layer_idx][expert_idx]

            shared_rank = shared_projection_rank(config, layer_idx, group_idx)
            base_rank_up = shared_rank
            base_rank_gate = shared_rank
            base_rank_down = shared_rank

            if flipped_down:
                down_in_features = compressed_int_size
                down_out_features = base_rank_down
            else:
                down_in_features = base_rank_down
                down_out_features = self.hidden_dim

            if "gate" in shared_weights:
                self.w1 = LatentLinear(
                    in_features=base_rank_gate,
                    out_features=compressed_int_size,
                    shared_weight_getter=lambda shared=shared_weights: (
                        shared["gate"] if shared is not None and "gate" in shared else None
                    ),
                    bias=False,
                    flipped_down=flipped_down,
                    is_down=False,
                )
                self.latent_w1 = True
            else:
                self.w1 = nn.Linear(self.hidden_dim, compressed_int_size, bias=False)

            if "down" in shared_weights:
                self.w2 = LatentLinear(
                    in_features=down_in_features,
                    out_features=down_out_features,  # d_model
                    shared_weight_getter=lambda shared=shared_weights: (
                        shared["down"] if shared is not None and "down" in shared else None
                    ),
                    bias=False,
                    flipped_down=flipped_down,
                    is_down=True,
                )
                self.latent_w2 = True
            else:
                self.w2 = nn.Linear(compressed_int_size, self.hidden_dim, bias=False)

            if "up" in shared_weights:
                self.w3 = LatentLinear(
                    in_features=base_rank_up,
                    out_features=compressed_int_size,
                    shared_weight_getter=lambda shared=shared_weights: (
                        shared["up"] if shared is not None and "up" in shared else None
                    ),
                    bias=False,
                    flipped_down=flipped_down,
                    is_down=False,
                )
                self.latent_w3 = True
            else:
                self.w3 = nn.Linear(self.hidden_dim, compressed_int_size, bias=False)

        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, hidden_states, hidden_up=None, hidden_gate=None, project_down=True):
        # hidden_up / hidden_gate are the inputs already projected by this
        # expert's shared P_up / P_gate ([T, r]); when absent the LatentLinear
        # applies the shared projection itself.
        if self.latent_w1:
            h_gate = hidden_gate if hidden_gate is not None else hidden_states
            gate_states = self.w1(h_gate, use_shared=hidden_gate is None)
        else:
            gate_states = self.w1(hidden_states)

        if self.latent_w3:
            h_up = hidden_up if hidden_up is not None else hidden_states
            up_states = self.w3(h_up, use_shared=hidden_up is None)
        else:
            up_states = self.w3(hidden_states)

        if self.latent_w2:
            return self.w2(self.act_fn(gate_states) * up_states, use_shared=project_down)
        return self.w2(self.act_fn(gate_states) * up_states)


class MixtralSparseMoeBlock(nn.Module):
    """
    This implementation is
    strictly equivalent to standard MoE with full capacity (no
    dropped tokens). It's faster since it formulates MoE operations
    in terms of block-sparse operations to accommodate imbalanced
    assignments of tokens to experts, whereas standard MoE either
    (1) drop tokens at the cost of reduced performance or (2) set
    capacity factor to number of experts and thus waste computation
    and memory on padding.
    """

    def __init__(self, config, layer_idx: int, shared_weights: nn.ModuleList | None = None):
        super().__init__()
        self.config = config
        self.hidden_dim = config.hidden_size
        self.ffn_dim = config.intermediate_size
        self.num_experts = config.num_local_experts
        self.top_k = config.num_experts_per_tok

        # The decoder layer owns this ModuleList. Keep only a tuple here to
        # avoid registering duplicate state-dict paths for shared parameters.
        self.shared_projs = tuple(shared_weights) if shared_weights is not None else ()
        self.expert_group_indices = config.expert_to_shared_proj[layer_idx]

        # gating

        # base_rank_up = config.base_ranks_up[layer_idx][0]
        # self.gate = nn.Linear(2 * base_rank_up, self.num_experts, bias=False)
        # self.old_gate = nn.Linear(self.hidden_dim, self.num_experts, bias=False)
        self.gate = nn.Linear(self.hidden_dim, self.num_experts, bias=False)
        # dmg_ranks = config.damage_deltas_ranks[layer_idx]

        # for expert_idx in range(self.num_experts):
        #     k = dmg_ranks[expert_idx]
        #     self.register_buffer(
        #         f"damage_u_{expert_idx}", torch.zeros(self.hidden_dim, k), persistent=True
        #     )
        #     self.register_buffer(f"damage_sigma_{expert_idx}", torch.zeros(k), persistent=True)
        # self.register_buffer("damage_gamma", torch.zeros((), dtype=torch.float32), persistent=True)
        # self.register_buffer(
        #     "damage_pbar", torch.zeros(self.num_experts, dtype=torch.float32), persistent=True
        # )
        # self.register_buffer(
        #     "damage_bias", torch.zeros(self.num_experts, dtype=torch.float32), persistent=True
        # )
        # self.register_buffer(
        #     "damage_meanresid", torch.zeros(self.num_experts, dtype=torch.float32), persistent=True
        # )

        self.experts = nn.ModuleList(
            [
                MixtralBlockSparseTop2MLP(
                    config,
                    layer_idx,
                    expert_idx,
                    shared_weights=(
                        self.shared_projs[self.expert_group_indices[expert_idx]]
                        if self.shared_projs
                        else None
                    ),
                )
                for expert_idx in range(self.num_experts)
            ]
        )

        # Jitter parameters
        self.jitter_noise = config.router_jitter_noise

    def _precompute_shared(self) -> bool:
        # x @ P_up / x @ P_gate is hoisted out of the experts only in the
        # flipped_down layout
        return bool(self.shared_projs)

    def _forward_grouped(
        self, hidden_states, expert_mask, expert_hit, routing_weights, final_hidden_states
    ):
        # Bucket the firing experts by shared-projection group. A group with no
        # firing expert never appears here, so it costs nothing.
        experts_by_group: dict[int, list[int]] = {}
        for expert_idx in expert_hit:
            experts_by_group.setdefault(self.expert_group_indices[expert_idx], []).append(
                expert_idx
            )

        # Token id -> row of that token in the current group's projected activations.
        # Entries written for earlier groups go stale, but each expert only reads the
        # rows of its own tokens, and those are always rewritten for its group.
        row_in_group = torch.empty(
            hidden_states.shape[0], dtype=torch.long, device=hidden_states.device
        )

        for group_idx, group_experts in experts_by_group.items():
            shared = self.shared_projs[group_idx]

            # Tokens routed to at least one expert of this group, in ascending order.
            # A token routed to two experts of the same group appears once, so it is
            # projected once and the result is shared by both experts.
            group_tokens = expert_mask[group_experts].sum(dim=(0, 1)).nonzero().squeeze(-1)

            # P_up / P_gate: [d, r]  ->  [T_g, r], with T_g = number of tokens routed to the group
            x_group = hidden_states[group_tokens]
            group_up = x_group @ shared["up"] if "up" in shared else None
            group_gate = x_group @ shared["gate"] if "gate" in shared else None

            row_in_group[group_tokens] = torch.arange(
                group_tokens.numel(), device=group_tokens.device
            )

            group_latent = (
                hidden_states.new_zeros(group_tokens.numel(), shared["down"].shape[1])
                if "down" in shared
                else None
            )

            for expert_idx in group_experts:
                idx, top_x = torch.where(expert_mask[expert_idx])
                rows = row_in_group[top_x]
                hidden_up = group_up[rows] if group_up is not None else None
                hidden_gate = group_gate[rows] if group_gate is not None else None

                if group_latent is None:
                    self._run_expert(
                        expert_idx,
                        hidden_states,
                        top_x,
                        idx,
                        routing_weights,
                        final_hidden_states,
                        hidden_up=hidden_up,
                        hidden_gate=hidden_gate,
                    )
                    continue

                latent = (
                    self.experts[expert_idx](
                        hidden_states[top_x],
                        hidden_up=hidden_up,
                        hidden_gate=hidden_gate,
                        project_down=False,
                    )
                    * routing_weights[top_x, idx, None]
                )
                group_latent.index_add_(0, rows, latent.to(group_latent.dtype))

            if group_latent is not None:
                final_hidden_states.index_add_(
                    0, group_tokens, (group_latent @ shared["down"].T).to(hidden_states.dtype)
                )

    def _run_expert(
        self,
        expert_idx,
        hidden_states,
        top_x,
        idx,
        routing_weights,
        final_hidden_states,
        hidden_up=None,
        hidden_gate=None,
    ):
        # top_x: token ids routed to this expert; idx: which of the top_k slots.
        # hidden_up / hidden_gate, when given, are x @ P for exactly those tokens.
        current_hidden_states = (
            self.experts[expert_idx](
                hidden_states[top_x],
                hidden_up=hidden_up,
                hidden_gate=hidden_gate,
            )
            * routing_weights[top_x, idx, None]
        )
        final_hidden_states.index_add_(0, top_x, current_hidden_states.to(hidden_states.dtype))

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        """ """
        batch_size, sequence_length, hidden_dim = hidden_states.shape
        if self.training and self.jitter_noise > 0:
            hidden_states *= torch.empty_like(hidden_states).uniform_(
                1.0 - self.jitter_noise, 1.0 + self.jitter_noise
            )

        hidden_states = hidden_states.view(-1, hidden_dim)  # [B*T, d]

        # P_up, P_gate = self.shared_projs["up"], self.shared_projs["gate"]
        # [d, r]

        # hidden_up = hidden_states @ P_up
        # hidden_gate = hidden_states @ P_gate
        # [T, r]

        # subspace_hidden_states = torch.cat([hidden_up, hidden_gate], dim=1)  # [T, 2r]

        # subspace_hidden_states: [T, 2r]
        # router_logits: [B*T, n_experts]
        # router_logits = self.gate(subspace_hidden_states)
        # else:
        # router_logits: (batch * sequence_length, n_experts)
        router_logits = self.gate(hidden_states)
        # router_logits = router_logits + self.damage_bias.to(router_logits.dtype)[None, :]
        # gamma = float(self.damage_gamma)
        # gamma = 0.0
        # if gamma != 0.0:
        #     if not hasattr(self, "_dmg_U"):  # build stacked tensors once
        #         kmax = max(
        #             (getattr(self, f"damage_u_{i}").shape[1] for i in range(self.num_experts)),
        #             default=0,
        #         )
        #         if kmax:
        #             U = hidden_states.new_zeros(self.num_experts, self.hidden_dim, kmax)
        #             S = hidden_states.new_zeros(self.num_experts, kmax)
        #             for i in range(self.num_experts):
        #                 u, s = getattr(self, f"damage_u_{i}"), getattr(self, f"damage_sigma_{i}")
        #                 ki = u.shape[1]
        #                 if ki:
        #                     U[i, :, :ki] = u.to(U)
        #                     S[i, :ki] = s.to(S)
        #             self._dmg_U, self._dmg_S = U, S
        #         else:
        #             self._dmg_U = None
        #     if self._dmg_U is not None:
        #         proj = torch.einsum("nd,edk->enk", hidden_states, self._dmg_U)  # [E, N, kmax], fp32
        #         p = (proj.pow(2) * self._dmg_S[:, None, :].pow(2)).sum(-1)  # [E, N]
        #         p = (p - self.damage_pbar[:, None]).clamp_min(0)  # center, then one-sided
        #         router_logits = router_logits - gamma * p.T.to(router_logits.dtype)

        routing_weights = F.softmax(router_logits, dim=1, dtype=torch.float)
        routing_weights, selected_experts = torch.topk(routing_weights, self.top_k, dim=-1)
        routing_weights /= routing_weights.sum(dim=-1, keepdim=True)
        # we cast back to the input dtype
        routing_weights = routing_weights.to(hidden_states.dtype)

        final_hidden_states = torch.zeros(
            (batch_size * sequence_length, hidden_dim),
            dtype=hidden_states.dtype,
            device=hidden_states.device,
        )

        # expert_mask[e, j, t] = 1 iff token t picked expert e as its j-th choice: [E, top_k, B*T]
        expert_mask = torch.nn.functional.one_hot(
            selected_experts, num_classes=self.num_experts
        ).permute(2, 1, 0)
        # Experts with at least one routed token, as Python ints (one host sync).
        expert_hit = torch.greater(expert_mask.sum(dim=(-1, -2)), 0).nonzero().flatten().tolist()

        if self._precompute_shared():
            self._forward_grouped(
                hidden_states, expert_mask, expert_hit, routing_weights, final_hidden_states
            )
        else:
            # No hoisted projection: each expert applies its shared P itself
            # (use_shared=True inside LatentLinear) or has no shared P at all.
            for expert_idx in expert_hit:
                idx, top_x = torch.where(expert_mask[expert_idx])
                self._run_expert(
                    expert_idx, hidden_states, top_x, idx, routing_weights, final_hidden_states
                )

        final_hidden_states = final_hidden_states.reshape(batch_size, sequence_length, hidden_dim)
        return final_hidden_states, router_logits


